  expiration_date = NULL;

COMMIT;

SELECT p.name AS payer, pr.state, pr.coverage_status, count(*) AS codes
  FROM payer_rule pr JOIN payer p ON p.id = pr.payer_id
 WHERE pr.created_by = 'extract:state-fee-schedule-2026-08'
 GROUP BY 1,2,3 ORDER BY 1,3;
